WITH valid AS (SELECT *, DATE_TRUNC('week', start_date) AS start_date_period FROM subscriptions WHERE customer_id IS NOT NULL AND end_date <= '2024-10-01') SELECT plan, DATE_TRUNC('WEEK', start_date_period) AS week_start, SIZE(COLLECT_SET(status)) AS num_status, (UNIX_TIMESTAMP(MAX(start_date_period)) - UNIX_TIMESTAMP(MIN(start_date_period))) / 60 AS duration_min, SUM(monthly_fee) FILTER (WHERE plan = 'basic') AS basic_total_monthly_fee FROM valid GROUP BY 1, 2
